"""Patch mobile Godot runtime using the exact tested desktop worker UI.

The patch fails closed if an upstream source changes. Original career data,
friend_dealer_stats, and stable worker role keys are preserved.
"""
def _apply(source: str, changes: list, label: str) -> str:
    for n, (old, new) in enumerate(changes):
        count = source.count(old)
        if count != 1:
            raise AssertionError(f"{label} anchor {n}: found {count}; refusing unsafe menu rewrite")
        source = source.replace(old, new, 1)
    return source

